export function parseClassroomRoster(input){if(!input||typeof input!=='object'||Array.isArray(input)||!Array.isArray(input.students))throw Error('O JSON deve conter uma lista students do Google Classroom.');if(input.students.length<1||input.students.length>300)throw Error('Importe de 1 a 300 alunos por arquivo.');return normalizeRoster(input.students.map(s=>({name:s?.profile?.name?.fullName,email:s?.profile?.emailAddress})));}
export function normalizeRoster(rows){if(!Array.isArray(rows)||rows.length<1||rows.length>300)throw Error('Lista inválida: de 1 a 300 registros.');const seen=new Set();return rows.map((r,index)=>{const name=typeof r?.name==='string'?r.name.trim():'',email=typeof r?.email==='string'?r.email.trim().toLowerCase():'';let issue=typeof r?.issue==='string'?r.issue.slice(0,120):'';if(!name||name.length>120)issue='Nome ausente ou maior que 120 caracteres';else if(email.length>250||!/^\S+@[^\s@]+\.[^\s@]+$/.test(email))issue='E-mail ausente ou inválido';else if(seen.has(email))issue='E-mail duplicado no arquivo';if(email)seen.add(email);return{index,name:name.slice(0,120),email:email.slice(0,250),issue};});}
